type stubNotifier struct {
	cfg       plugin.TeamsConfig
	version   string
	changelog string
	err       error
	called    bool
}

func (s *stubNotifier) Notify(_ context.Context, version, changelog string) error {
	s.called = true
	s.version = version
	s.changelog = changelog
	return s.err
}

func TestRunSuccess(t *testing.T) {
	stub := &stubNotifier{}
	original := newNotifier
	newNotifier = func(cfg plugin.TeamsConfig) notifier {
		stub.cfg = cfg
		return stub
	}
	defer func() { newNotifier = original }()

	stdout := &bytes.Buffer{}
	stderr := &bytes.Buffer{}
	exitCode := run(context.Background(), env(map[string]string{
		"SEMREL_PLUGIN_WEBHOOK_URL": "https://example.test/webhook",
		"SEMREL_VERSION":            "v1.2.3",
		"SEMREL_CHANGELOG":          "- feature",
		"SEMREL_PLUGIN_TITLE":       "Shipped",
		"SEMREL_PLUGIN_THEME_COLOR": "00FF00",
		"SEMREL_PLUGIN_MENTION":     "user@example.com",
	}), stdout, stderr)

	require.Equal(t, 0, exitCode)
	require.Equal(t, "plugin_schema_version=1\n", stderr.String())
	require.True(t, stub.called)
	require.Equal(t, "v1.2.3", stub.version)
	require.Equal(t, "- feature", stub.changelog)
	require.Equal(t, "Shipped", stub.cfg.Title)
	require.Equal(t, "00FF00", stub.cfg.ThemeColor)
	require.Equal(t, "user@example.com", stub.cfg.Mention)
}

func TestRunDryRun(t *testing.T) {
	stub := &stubNotifier{}
	original := newNotifier
	newNotifier = func(cfg plugin.TeamsConfig) notifier {
		stub.cfg = cfg
		return stub
	}
	defer func() { newNotifier = original }()

	secret := "teams-secret-webhook-segment"
	stdout := &bytes.Buffer{}
	stderr := &bytes.Buffer{}
	exitCode := run(context.Background(), env(map[string]string{
		"SEMREL_PLUGIN_WEBHOOK_URL": "https://example.test/webhook/" + secret,
		"SEMREL_TAG_NAME":           "v2.0.0",
		"SEMREL_CHANGELOG":          "- teams dry-run",
		"SEMREL_DRY_RUN":            "true",
	}), stdout, stderr)
	require.Equal(t, 0, exitCode)
	require.False(t, stub.called)
	require.NotContains(t, stdout.String(), secret)
	require.NotContains(t, stderr.String(), secret)
	require.Contains(t, stderr.String(), "plugin_schema_version=1\n")
	require.Contains(t, stderr.String(), "[dry-run] hook-teams: would send Teams notification for v2.0.0 to https://example.test/webhook/***")

	var payload plugin.TeamsPayload
	require.NoError(t, json.Unmarshal(stdout.Bytes(), &payload))
	require.Equal(t, "https://example.test/webhook/***", payload.Destination)
	require.Equal(t, "New release v2.0.0", payload.Summary)
}

func TestRunDryRunWithoutWebhookURL(t *testing.T) {
	stdout := &bytes.Buffer{}
	stderr := &bytes.Buffer{}
	exitCode := run(context.Background(), env(map[string]string{
		"SEMREL_VERSION": "v2.0.0",
		"SEMREL_DRY_RUN": "true",
	}), stdout, stderr)

	require.Equal(t, 0, exitCode)
	require.Contains(t, stderr.String(), "[dry-run] hook-teams: would need SEMREL_PLUGIN_WEBHOOK_URL to send notification")
	require.Contains(t, stderr.String(), "[dry-run] hook-teams: would send Teams notification for v2.0.0 to <unset>")

	var payload plugin.TeamsPayload
	require.NoError(t, json.Unmarshal(stdout.Bytes(), &payload))
	require.Equal(t, "<unset>", payload.Destination)
}

